WITH flattened AS (SELECT id, status_code, k, attr_value FROM app_logs LATERAL VIEW EXPLODE(context) x AS k, attr_value), parsed AS (SELECT id, status_code, k, CAST((status_code & 8) != 0 AS INT) AS has_fault, SHIFTRIGHT(status_code, 2) AS status_code_high FROM flattened), with_windows AS (SELECT id, status_code, k, has_fault, LAG(status_code_high) OVER w_hist AS prev_status_code_high, LAG(has_fault) OVER w_hist AS prev_has_fault, ROW_NUMBER() OVER w_hist AS event_seq, LAST_VALUE(status_code_high, TRUE) OVER w_ordered AS last_known_status_code_high FROM parsed WHERE k = 'trace' WINDOW w_hist AS (PARTITION BY k ORDER BY status_code_high ASC, id ASC, k ASC), w_ordered AS (PARTITION BY k ORDER BY has_fault ASC, id ASC, k ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)), scored AS (SELECT id, status_code, k, prev_has_fault, MIN(has_fault) OVER w_ordered AS running_min_has_fault, MAX(has_fault) OVER w_ordered AS running_max_has_fault, AVG(has_fault) OVER w_ordered AS running_avg_has_fault, LEAD(prev_has_fault, 1) OVER (PARTITION BY k ORDER BY last_known_status_code_high ASC, id ASC, k ASC) AS next_prev_has_fault FROM with_windows WINDOW w_ordered AS (PARTITION BY k ORDER BY prev_has_fault ASC, id ASC, k ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)) SELECT CASE WHEN prev_has_fault >= 1 THEN 'HIGH' ELSE 'LOW' END AS prev_has_fault_tier, SORT_ARRAY(COLLECT_SET(k)) AS k_list, SORT_ARRAY(COLLECT_SET(k)) AS k_list_2, COUNT(CASE WHEN k = 'version' THEN 1 END) AS version_count FROM scored GROUP BY prev_has_fault_tier ORDER BY version_count ASC NULLS FIRST;
